import UIKit
import UniformTypeIdentifiers

/// Guarda en Recientes lo que hay en el portapapeles: textos, enlaces e imágenes, incluso
/// cuando se han copiado varios elementos a la vez.
enum ClipboardCapture {
    /// Marcas que usan los gestores de contraseñas para pedir que no se guarde lo copiado.
    static let privateMarkerTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword"
    ]

    /// Elementos que se leen como máximo de una misma copia.
    static let maximumItems = 10

    static func isPrivate(types: [String]) -> Bool {
        types.contains { privateMarkerTypes.contains($0) }
    }

    /// Devuelve `true` si se ha añadido algo a Recientes.
    @discardableResult
    static func captureItems(from pasteboard: UIPasteboard, changeCount: Int) -> Bool {
        guard !isPrivate(types: pasteboard.types) else { return false }
        let count = pasteboard.numberOfItems
        guard count > 1 else { return captureSingleItem(from: pasteboard, changeCount: changeCount) }

        var captured = false
        // Se recorren al revés para que el primer elemento copiado quede el más reciente.
        for index in (0..<min(count, maximumItems)).reversed() {
            let itemSet = IndexSet(integer: index)
            let types = pasteboard.types(forItemSet: itemSet)?.first ?? []
            guard !isPrivate(types: types) else { continue }

            if let imageType = types.first(where: { UTType($0)?.conforms(to: .image) == true }),
               let data = pasteboard.data(forPasteboardType: imageType, inItemSet: itemSet)?.first {
                captured = captureImage(data, changeCount: nil) || captured
            } else if let textType = types.first(where: { isText($0) }),
                      let data = pasteboard.data(forPasteboardType: textType, inItemSet: itemSet)?.first,
                      let text = String(data: data, encoding: .utf8) ?? String(data: data, encoding: .utf16) {
                captured = captureText(text, changeCount: nil) || captured
            }
        }
        return captured
    }

    @discardableResult
    static func captureText(_ text: String, changeCount: Int?) -> Bool {
        let value = text
        guard !value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return false }
        if SharedClipboardStore.skipOneTimeCodes, KeyboardTextLogic.isLikelyOneTimeCode(value) { return false }

        var isSensitive = false
        if ClipboardClassifier.isSensitive(value) {
            switch SharedClipboardStore.sensitiveMode {
            case .skip: return false
            case .mask: isSensitive = true
            case .normal: break
            }
        }
        return SharedClipboardStore.captureTemporaryText(
            value,
            pasteboardChangeCount: changeCount,
            isSensitive: isSensitive
        )
    }

    @discardableResult
    static func captureImage(_ data: Data, changeCount: Int?) -> Bool {
        guard let jpeg = ClipImageProcessing.jpegThumbnail(from: data, maxPixelSize: 1_600) else { return false }
        return SharedClipboardStore.captureTemporaryImage(
            jpeg,
            hash: ClipImageProcessing.hash(jpeg),
            pasteboardChangeCount: changeCount
        )
    }

    private static func captureSingleItem(from pasteboard: UIPasteboard, changeCount: Int) -> Bool {
        if pasteboard.hasStrings, let text = pasteboard.string {
            return captureText(text, changeCount: changeCount)
        }
        if pasteboard.hasImages, let data = ClipImageProcessing.pasteboardImageData(pasteboard) {
            return captureImage(data, changeCount: changeCount)
        }
        if pasteboard.hasURLs, let url = pasteboard.url {
            return captureText(url.absoluteString, changeCount: changeCount)
        }
        return false
    }

    private static func isText(_ type: String) -> Bool {
        guard let utType = UTType(type), !utType.conforms(to: .fileURL) else { return false }
        return utType.conforms(to: .plainText) || utType.conforms(to: .url)
    }
}
